window.kbPageData["views/entry/k-4266ddfa58bd3be9"] = {"key":"entry/k-4266ddfa58bd3be9","state":{"route":"entry/k-4266ddfa58bd3be9"},"node":{"id":"k-4266ddfa58bd3be9","mode":"k","title":"补集计数原理","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":[],"qs":["江苏 2023 A类 行测#60"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"在给定的计数范围内，满足某条件的情况数等于总情况数减去不满足该条件的情况数。分多类扣除时，要避免重复计数。","review":{"definition":"在给定的计数范围内，满足某条件的情况数等于总情况数减去不满足该条件的情况数。分多类扣除时，要避免重复计数。","explanation":"本题先保留每天展出两类、相邻两天不重复、第1天不展出玉器和国画的限制，暂时放宽五类均须展出的要求。第1天从其余三类中选两类，之后每天从前一天未展出的三类中选两类，共有3⁴＝81种。任意相邻两天已展出四个不同类别，所以至多遗漏一类。指定遗漏一类后，剩下四类中，第1天一旦选定，后续每天只能展出前一天未展出的两类。若遗漏玉器或国画，第1天各有3种选法，共6种。若遗漏青铜器、瓷器或书法，第1天各只有1种选法，共3种。因此符合全部条件的安排有81－6－3＝72种，选A。","references":[],"evidence":"满足条件的情况数=总情况数-不满足条件的情况数=81-6-3=72种。","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2023 A类 行测#60":{"paper":"江苏 2023 A类 行测","n":60,"mod":"数量关系","src":["22304fe4c340e19d7902.pdf",11],"asrc":["be17f9afe070cf13a0fb.pdf",17],"card":"9479a58ec9bdb0fae03bb9ad","links":[{"id":"k-4266ddfa58bd3be9","role":"解题依据","why":"符合逐日安排限制的总数扣除遗漏类别的安排数，即得到五类均展出的排法数。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-4266ddfa58bd3be9":[["江苏 2023 A类 行测#60"]]}};
